package pathcollate

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"slices"
	"strings"
	"testing"

	"golang.org/x/text/unicode/norm"
)

func TestKey(t *testing.T) {
	// Expected comparisons were generated by Node 26.8.2 / ICU 78.3, en-US localeCompare.
	for _, test := range []struct {
		name   string
		first  string
		second string
		want   int
	}{
		{
			name:   "emoji precedes Latin",
			first:  "🤖.txt",
			second: "a.txt",
			want:   -1,
		},
		{
			name:   "Unicode 17 emoji precedes Latin",
			first:  "🫪.txt",
			second: "a.txt",
			want:   -1,
		},
		{
			name:   "lowercase first",
			first:  "a.txt",
			second: "A.txt",
			want:   -1,
		},
		{
			name:   "ligature expansion",
			first:  "ae.txt",
			second: "æ.txt",
			want:   -1,
		},
		{
			name:   "case bits do not outrank compatibility weights",
			first:  "A",
			second: "ₐ",
			want:   -1,
		},
		{
			name:   "Kana compatibility weights",
			first:  "あ",
			second: "㋐",
			want:   -1,
		},
		{
			name:   "root Han radical order",
			first:  "𠀀",
			second: "三",
			want:   -1,
		},
		{
			name:   "last assigned Han precedes unassigned",
			first:  "\U00033479",
			second: "\U0003347a",
			want:   -1,
		},
		{
			name:   "canonical equivalence",
			first:  "é",
			second: "e\u0301",
			want:   0,
		},
		{
			name:   "Hangul decomposition",
			first:  "각",
			second: "각",
			want:   0,
		},
		{
			name:   "canonical mark reordering",
			first:  "a\u0301\u0327",
			second: "a\u0327\u0301",
			want:   0,
		},
		{
			name: "long combining sequence has no stream-safe boundary",
			first: "a" + strings.Repeat(
				"\u0300",
				31,
			) + "\u0327",
			second: "a\u0327" + strings.Repeat(
				"\u0300",
				31,
			),
			want: 0,
		},
		{
			name:   "explicit combining grapheme joiner is ignorable",
			first:  "a\u034f\u0301",
			second: "a\u0301",
			want:   0,
		},
		{
			name:   "discontiguous contraction",
			first:  "и\u0327\u0306",
			second: "й\u0327",
			want:   0,
		},
		{
			name:   "skipped marks form a contraction with subsequent input",
			first:  "\u0f71\u0f71\u0f72\u0f72.txt",
			second: "\u0f73\u0f72.txt",
			want:   1,
		},
		{
			name:   "replayed marks with Cyrillic prefix and punctuation",
			first:  "\u0387\u0418\u0f71\u0f72\u0327\u0306e.txt",
			second: "\u200d\u00b7\u0438\u0306\u0315\u0f72\u0301.txt",
			want:   1,
		},
		{
			name:   "replayed marks with Latin prefix",
			first:  "la\u0f71\u0f72\u0f71\u0f72\u0327.txt",
			second: "la\u0301\u0f72\u0f71\u0f72\u0327.txt",
			want:   1,
		},
		{
			name:   "three Tibetan marks interleave with two contractions",
			first:  "l\u0f72\u0f71\u0f72\u0f71\u0f72\u064a.txt",
			second: "l\u0f72\u0f71\u0306\u0315\u0f72\u0387.txt",
			want:   1,
		},
		{
			name:   "grapheme joiner bounds replayed contractions",
			first:  "\u0438\u0f72\u0f71\u0f72\u0f71\u034f\u0387.txt",
			second: "\u0438\u0323\u0f71\u0f72\u0327\u0f72l.txt",
			want:   1,
		},
		{
			name:   "Tibetan and Cyrillic contractions share skipped marks",
			first:  "\u0438\u0f72\u0f71\u0306\u0f71i\u0315.txt",
			second: "\u0327\u0418\u0327\u0f72\u0315\u0306\u0f71.txt",
			want:   1,
		},
		{
			name:   "replayed contraction continues past Cyrillic contraction",
			first:  "\u0438\u0306\u0f71\u0f72l\u0f72\u064a.txt",
			second: "\u0438\u0f72\u0306",
			want:   1,
		},
		{
			name:   "replayed contractions preserve Arabic following input",
			first:  "\u064a\u0f72\u0f71\u0323\u0f71\u0f72\u0f71.txt",
			second: "\u064a\u0f72\u0f71\u0f72\u0387\u0306\u064a.txt",
			want:   1,
		},
		{
			name:   "replayed contraction precedes remaining Thai input",
			first:  "\u0f71\u0f72\u0301\u0f72\u0f71\u0e40l.txt",
			second: "\u0f71\u0f72\u0f72",
			want:   1,
		},
		{
			name:   "equal combining class blocks contraction",
			first:  "и\u0301\u0306",
			second: "й\u0301",
			want:   -1,
		},
		{
			name:   "middle dot prefix",
			first:  "l·",
			second: "l.",
			want:   -1,
		},
		{
			name:   "canonical prefix contraction",
			first:  "l·",
			second: "l·",
			want:   0,
		},
		{
			name:   "unassigned script boundary",
			first:  "\ufdd1\ufdd0",
			second: "\U0010ffff",
			want:   -1,
		},
		{
			name:   "reserved Hangul boundary matches original syllable",
			first:  "\ufdd1가",
			second: "\ufdd1가",
			want:   -1,
		},
		{
			name:   "reserved Hangul boundary does not consume another syllable prefix",
			first:  "\ufdd1각",
			second: "\ufdd1각",
			want:   0,
		},
		{
			name:   "noncharacter after replacement character",
			first:  "\uffff",
			second: "\ufffd",
			want:   1,
		},
		{
			name:   "merge separator precedes punctuation",
			first:  "\ufffe",
			second: "\t",
			want:   -1,
		},
		{
			name:   "empty text",
			first:  "",
			second: "a",
			want:   -1,
		},
		{
			name:   "fully ignorable",
			first:  "\x00",
			second: "",
			want:   0,
		},
	} {
		t.Run(
			test.name,
			func(t *testing.T) {
				first, second := Key(test.first), Key(test.second)
				if got := bytes.Compare(
					first,
					second,
				); got != test.want {
					t.Fatalf(
						"comparison of %q and %q = %d; want %d",
						test.first,
						test.second,
						got,
						test.want,
					)
				}
				if got := bytes.Compare(
					second,
					first,
				); got != -test.want {
					t.Fatalf(
						"reverse comparison = %d; want %d",
						got,
						-test.want,
					)
				}
			},
		)
	}
}

func TestRootCorpus(t *testing.T) {
	// This input is independent of the generated tables. The digest was computed
	// from the stable localeCompare sort in Node 26.8.2 / ICU 78.3, en-US.
	// It covers all BMP scalars, supplementary scripts/emoji, current Han blocks,
	// tag characters, and later-plane/unassigned/noncharacter boundaries.
	if norm.Version != "17.0.0" {
		t.Fatalf(
			"normalization version %s differs from the pinned collation data",
			norm.Version,
		)
	}
	type character struct {
		text string
		key  []byte
	}
	var characters []character
	for _, interval := range [][2]rune{
		{
			0,
			0xd7ff,
		},
		{
			0xe000,
			0x33479,
		},
		{
			0xe0000,
			0xe007f,
		},
	} {
		for r := interval[0]; r <= interval[1]; r++ {
			s := string(r)
			characters = append(
				characters,
				character{
					text: s,
					key:  Key(s),
				},
			)
		}
	}
	for plane := rune(4); plane <= 16; plane++ {
		for _, offset := range []rune{
			0,
			1,
			0xfffe,
			0xffff,
		} {
			s := string(plane*65536 + offset)
			characters = append(
				characters,
				character{
					text: s,
					key:  Key(s),
				},
			)
		}
	}
	alphabet := []rune("aAeElLæǺ̧̀̆̊̕ͅ͏··🤖🫩🫪𠀀三ぁアกเЙиؤاأकष்က각가각ჼ𝔸\U0010ffff\ufdd0\ufdd1")
	seed := uint32(39285017)
	next := func(bound int) int {
		seed = seed*1664525 + 1013904223
		return int(seed % uint32(bound))
	}
	var mixed []character
	for range 10000 {
		var text strings.Builder
		for range 1 + next(7) {
			text.WriteRune(alphabet[next(len(alphabet))])
		}
		text.WriteString(".md")
		s := text.String()
		mixed = append(
			mixed,
			character{
				text: s,
				key:  Key(s),
			},
		)
	}
	for _, test := range []struct {
		name       string
		characters []character
		want       string
	}{
		{
			name:       "208174 scalar values",
			characters: characters,
			want:       "491b35bf4a7b685d7e097aad180ee0a0ab89efb7e611336a0f4c91562ac57680",
		},
		{
			name:       "10000 mixed-script paths",
			characters: mixed,
			want:       "06ae0a12e99dc5173172871cf0b92683739dc9fd547b7355b60f955c89976ed7",
		},
	} {
		t.Run(
			test.name,
			func(t *testing.T) {
				slices.SortStableFunc(
					test.characters,
					func(a, b character) int {
						return bytes.Compare(
							a.key,
							b.key,
						)
					},
				)
				hash := sha256.New()
				for _, character := range test.characters {
					_, _ = hash.Write([]byte(character.text))
				}
				if got := fmt.Sprintf(
					"%x",
					hash.Sum(nil),
				); got != test.want {
					t.Fatalf(
						"Node root-order corpus digest = %s; want %s",
						got,
						test.want,
					)
				}
			},
		)
	}
}
